  "contents": "export class Account {
  constructor(name, balance = 0) {
    this.name = name;
    this._balance = balance;
  }

  get balance() {
    return this._balance;
  }

  apply(cents) {
    this._balance += cents;
  }
}

export function totalBalance(accounts) {
  return accounts.reduce((total, account) => total + account.balance, 0);
}
